def evaluate(current_reputation, observation, my_history, round_num):
    # Weight that decays with round number (earlier rounds have less impact)
    weight = 1.0 / (1.0 + round_num * 0.1)

    # Get recent actions of other agents (if available)
    recent_window = observation.get('recent_window', [])
    if recent_window:
        coop_count = sum(1 for entry in recent_window if entry.get('action') == 'cooperate')
        coop_ratio = coop_count / len(recent_window)
    else:
        coop_ratio = 0.5  # neutral assumption if no data

    # Base update for the action
    if observation['action'] == 'cooperate':
        # Reward cooperation more when others cooperate, less when they defect
        base = weight * (0.5 + 0.5 * coop_ratio)  # range [0.25*weight, 0.5*weight]
    else:  # defect
        # Penalize defection more when others cooperate, less when they defect
        base = -weight * (0.5 + 0.5 * (1 - coop_ratio))  # range [-0.5*weight, -0.25*weight]

    # Clamp to [-1, 1]
    return max(-1.0, min(1.0, base))

