def evaluate(current_reputation, observation, my_history, round_num):
    # Base update magnitude
    base_reward = 0.3
    base_penalty = -0.3

    # Determine direction from the observed action
    if observation['action'] == 'cooperate':
        update = base_reward
    else:  # defect
        update = base_penalty

    # Use recent_window to detect community trend
    recent_window = observation.get('recent_window', [])
    if recent_window:
        coop_count = sum(1 for entry in recent_window if entry.get('action') == 'cooperate')
        community_coop_rate = coop_count / len(recent_window)
    else:
        community_coop_rate = 0.5  # neutral if no info

    # Adjust based on how the action aligns with community
    if community_coop_rate > 0.6:
        # Most others cooperate – reward cooperation more, punish defection more
        if observation['action'] == 'cooperate':
            update += 0.1
        else:
            update -= 0.2
    elif community_coop_rate < 0.4:
        # Most others defect – reward cooperation slightly, punish defection less
        if observation['action'] == 'cooperate':
            update += 0.05
        else:
            update -= 0.1
    # else: no adjustment

    # Use own recent behavior to modulate (hypocrisy effect)
    own_recent = my_history[-10:] if len(my_history) >= 10 else my_history
    own_coop_count = sum(1 for act in own_recent if act == 'cooperate')
    own_coop_rate = own_coop_count / len(own_recent) if own_recent else 0.5

    if own_coop_rate < 0.3:
        # Very selfish: dampen the update (more forgiving)
        update *= 0.7
    elif own_coop_rate > 0.8:
        # Very cooperative: amplify the update (harsher on defectors)
        update *= 1.2
    # else: no change

    # Clamp to [-1, 1] and return
    return max(-1.0, min(1.0, update))


def decide(recipient_reputation, round_num, my_history):
    # Base threshold: increases with rounds but saturates
    if round_num < 50:
        threshold = 0.2 + 0.4 * (round_num / 50.0)
    else:
        threshold = 0.6

    # Adjust threshold based on own recent cooperation rate
    own_recent = my_history[-10:] if len(my_history) >= 10 else my_history
    if own_recent:
        own_coop_count = sum(1 for act in own_recent if act == 'cooperate')
        own_coop_rate = own_coop_count / len(own_recent)
    else:
        own_coop_rate = 0.5

    if own_coop_rate > 0.7:
        threshold -= 0.1  # more forgiving when we are cooperative
    elif own_coop_rate < 0.3:
        threshold += 0.1  # harsher when we are selfish

    # Reset if we have defected in the last 3 rounds
    if len(my_history) >= 3:
        if all(act == 'defect' for act in my_history[-3:]):
            return True  # cooperate to break the streak

    # Standard decision based on reputation
    return recipient_reputation > threshold
